function Get-Sha256Hex([byte[]]$Bytes) {
    $sha=[System.Security.Cryptography.SHA256]::Create()
    try { return ([BitConverter]::ToString($sha.ComputeHash($Bytes))).Replace("-","").ToLowerInvariant() }
    finally { $sha.Dispose() }
}

function Assert-BytesAt([byte[]]$Data,[int]$Offset,[byte[]]$Expected) {
    if ($Offset -lt 0 -or $Offset + $Expected.Length -gt $Data.Length) { throw "Patch range is outside index.js. offset=$Offset" }
    for ($i=0;$i -lt $Expected.Length;$i++) {
        if ($Data[$Offset+$i] -ne $Expected[$i]) { throw "Patch byte verification failed. offset=$Offset" }
    }
}

function Apply-StaticPatches([byte[]]$Data,$Patches,[string]$ExpectedSha,[string]$StageName) {
    $decoded=@()
    [Int64]$finalLen=$Data.Length
    $lastOffset=-1
    foreach ($p in $Patches) {
        $off=[int]$p.Offset
        if ($off -lt $lastOffset) { throw "$StageName patch table is not sorted." }
        [byte[]]$old=[Convert]::FromBase64String($p.Old)
        [byte[]]$new=[Convert]::FromBase64String($p.New)
        Assert-BytesAt $Data $off $old
        $decoded += [pscustomobject]@{ Offset=$off; Old=$old; New=$new }
        $finalLen += $new.Length-$old.Length
        $lastOffset=$off
    }
    [byte[]]$out=New-Object byte[] ([int]$finalLen)
    $srcPos=0; $dstPos=0
    foreach ($x in $decoded) {
        $off=[int]$x.Offset; [byte[]]$old=$x.Old; [byte[]]$new=$x.New
        if ($off -lt $srcPos) { throw "$StageName patches overlap at offset=$off" }
        $copyLen=$off-$srcPos
        if ($copyLen -gt 0) { [Array]::Copy($Data,$srcPos,$out,$dstPos,$copyLen); $dstPos+=$copyLen }
        if ($new.Length -gt 0) { [Array]::Copy($new,0,$out,$dstPos,$new.Length); $dstPos+=$new.Length }
        $srcPos=$off+$old.Length
    }
    $tailLen=$Data.Length-$srcPos
    if ($tailLen -gt 0) { [Array]::Copy($Data,$srcPos,$out,$dstPos,$tailLen); $dstPos+=$tailLen }
    if ($dstPos -ne $out.Length) { throw "$StageName output length mismatch." }
    $hash=Get-Sha256Hex $out
    if ($hash -ne $ExpectedSha) { throw "$StageName SHA-256 verification failed. got=$hash" }
    return $out
}

Write-Host "HackHub Korean Patch - Final Integrated Mission-Safe Build"
Write-Host "Checking clean app.asar..."
if (-not (Test-Path -LiteralPath $AsarPath)) { throw "app.asar was not found. Put this script in the HackHub resources folder." }
$actualSize=(Get-Item -LiteralPath $AsarPath).Length
$actualSha=(Get-FileHash -LiteralPath $AsarPath -Algorithm SHA256).Hash.ToLowerInvariant()
if ($actualSize -ne $ExpectedAsarSize -or $actualSha -ne $ExpectedAsarSha256) {
    throw "Unsupported app.asar. Restore the clean Steam file first. Expected SHA256=$ExpectedAsarSha256 ; Current SHA256=$actualSha"
}

if (-not (Test-Path -LiteralPath $BackupPath)) {
    Write-Host "Creating clean backup: app.asar.original.bak"
    Copy-Item -LiteralPath $AsarPath -Destination $BackupPath
} else {
    $backupSize=(Get-Item -LiteralPath $BackupPath).Length
    $backupSha=(Get-FileHash -LiteralPath $BackupPath -Algorithm SHA256).Hash.ToLowerInvariant()
    if ($backupSize -ne $ExpectedAsarSize -or $backupSha -ne $ExpectedAsarSha256) { throw "Existing app.asar.original.bak is not the supported clean original." }
    Write-Host "Keeping existing verified clean backup."
}
if (Test-Path -LiteralPath $TempPath) { Remove-Item -LiteralPath $TempPath -Force }

$srcFs=$null
try {
    $utf8=New-Object System.Text.UTF8Encoding($false)
    $srcFs=[System.IO.File]::Open($AsarPath,[System.IO.FileMode]::Open,[System.IO.FileAccess]::Read,[System.IO.FileShare]::Read)
    [byte[]]$preamble=New-Object byte[] 16
    if ($srcFs.Read($preamble,0,16) -ne 16) { throw "Could not read ASAR preamble." }
    $headerPickleSize=[BitConverter]::ToUInt32($preamble,4)
    $jsonLength=[BitConverter]::ToUInt32($preamble,12)
    [Int64]$payloadStart=8+[Int64]$headerPickleSize
    [byte[]]$headerBytes=New-Object byte[] $jsonLength
    $srcFs.Position=16
    if ($srcFs.Read($headerBytes,0,$headerBytes.Length) -ne $headerBytes.Length) { throw "Could not read ASAR JSON header." }
    $headerText=$utf8.GetString($headerBytes)
    $metaPattern='"size":(?<size>\d+),"offset":"'+$KnownIndexOffset+'","integrity":\{"algorithm":"SHA256","hash":"(?<hash>[0-9a-f]{64})","blockSize":4194304,"blocks":\[(?<blocks>[^\]]*)\]\}'
    $metaMatches=[regex]::Matches($headerText,$metaPattern)
    if ($metaMatches.Count -ne 1) { throw "Could not uniquely locate dist/assets/index.js metadata." }
    $meta=$metaMatches[0]
    [Int64]$currentIndexSize=[Int64]::Parse($meta.Groups['size'].Value)
    [Int64]$indexAbsoluteOffset=$payloadStart+[Int64]$KnownIndexOffset
    [byte[]]$indexBytes=New-Object byte[] $currentIndexSize
    $srcFs.Position=$indexAbsoluteOffset
    $got=0
    while ($got -lt $indexBytes.Length) {
        $n=$srcFs.Read($indexBytes,$got,$indexBytes.Length-$got)
        if ($n -le 0) { throw "Could not fully read index.js." }
        $got+=$n
    }
    if ((Get-Sha256Hex $indexBytes) -ne $ExpectedIndexSha256) { throw "Clean index.js SHA-256 mismatch." }

    Write-Host "Applying base localization improvements..."
    [byte[]]$stage1=Apply-StaticPatches $indexBytes $Stage1Patches $ExpectedStage1IndexSha256 "Stage 1"
    Write-Host "Applying deep audit and mission-safe fixes..."
    [byte[]]$newIndex=Apply-StaticPatches $stage1 $Stage2Patches $ExpectedFinalIndexSha256 "Stage 2"

    [Int64]$delta=[Int64]$newIndex.Length-$currentIndexSize
    Write-Host "index.js: $currentIndexSize -> $($newIndex.Length) bytes (delta $delta)"

    $newBlocks=@()
    for ($offset=0;$offset -lt $newIndex.Length;$offset+=$BlockSize) {
        $len=[Math]::Min($BlockSize,$newIndex.Length-$offset)
        [byte[]]$block=New-Object byte[] $len
        [Array]::Copy($newIndex,$offset,$block,0,$len)
        $newBlocks+=(Get-Sha256Hex $block)
    }
    $blockJson=($newBlocks | ForEach-Object { '"'+$_+'"' }) -join ','
    $offsetPattern='"offset":"(\d+)"'
    $offsetEvaluator=[System.Text.RegularExpressions.MatchEvaluator]{
        param($m)
        [Int64]$n=[Int64]::Parse($m.Groups[1].Value)
        if ($n -gt [Int64]$KnownIndexOffset) { $n+=$delta }
        return '"offset":"'+$n.ToString()+'"'
    }
    $headerShifted=[regex]::Replace($headerText,$offsetPattern,$offsetEvaluator)
    $newMeta='"size":'+$newIndex.Length+',"offset":"'+$KnownIndexOffset+'","integrity":{"algorithm":"SHA256","hash":"'+(Get-Sha256Hex $newIndex)+'","blockSize":4194304,"blocks":['+$blockJson+']}'
    if ($headerShifted.IndexOf($meta.Value,[StringComparison]::Ordinal) -lt 0) { throw "Could not locate index.js metadata replacement point." }
    $newHeaderText=$headerShifted.Replace($meta.Value,$newMeta)
    [byte[]]$newHeader=$utf8.GetBytes($newHeaderText)
    if ($newHeader.Length -ne $jsonLength) { throw "ASAR header byte length changed; aborting for safety." }

    $dstFs=[System.IO.File]::Open($TempPath,[System.IO.FileMode]::CreateNew,[System.IO.FileAccess]::ReadWrite,[System.IO.FileShare]::None)
    try {
        $dstFs.Write($preamble,0,$preamble.Length)
        $dstFs.Write($newHeader,0,$newHeader.Length)
        [Int64]$paddingLen=$payloadStart-16-$jsonLength
        if ($paddingLen -gt 0) {
            [byte[]]$padding=New-Object byte[] $paddingLen
            $srcFs.Position=16+$jsonLength
            if ($srcFs.Read($padding,0,$padding.Length) -ne $padding.Length) { throw "Could not read header padding." }
            $dstFs.Write($padding,0,$padding.Length)
        }
        $srcFs.Position=$payloadStart
        [Int64]$remaining=[Int64]$KnownIndexOffset
        [byte[]]$buf=New-Object byte[] 8388608
        while ($remaining -gt 0) {
            $want=[int][Math]::Min([Int64]$buf.Length,$remaining)
            $n=$srcFs.Read($buf,0,$want)
            if ($n -le 0) { throw "Unexpected EOF before index.js." }
            $dstFs.Write($buf,0,$n); $remaining-=$n
        }
        $dstFs.Write($newIndex,0,$newIndex.Length)
        $srcFs.Position=$indexAbsoluteOffset+$currentIndexSize
        while (($n=$srcFs.Read($buf,0,$buf.Length)) -gt 0) { $dstFs.Write($buf,0,$n) }
        $dstFs.Flush()
        if ($dstFs.Length -ne $ExpectedFinalAsarSize) { throw "Final ASAR size mismatch. got=$($dstFs.Length)" }
    }
    finally { if ($dstFs) { $dstFs.Dispose() } }

    $srcFs.Dispose(); $srcFs=$null
    $tempSha=(Get-FileHash -LiteralPath $TempPath -Algorithm SHA256).Hash.ToLowerInvariant()
    if ($tempSha -ne $ExpectedFinalAsarSha256) { throw "Final ASAR SHA-256 verification failed. got=$tempSha" }

    Remove-Item -LiteralPath $AsarPath -Force
    Move-Item -LiteralPath $TempPath -Destination $AsarPath
    Write-Host ""
    Write-Host "Patch completed and verified." -ForegroundColor Green
    Write-Host "Stage 1 patches: $($Stage1Patches.Count)"
    Write-Host "Stage 2 audit patches: $($Stage2Patches.Count)"
    Write-Host "Final index SHA256: $ExpectedFinalIndexSha256"
    Write-Host "Final app.asar SHA256: $ExpectedFinalAsarSha256"
    Write-Host "Clean backup: app.asar.original.bak"
}
catch {
    Write-Host ""
    Write-Host "Patch failed: $($_.Exception.Message)" -ForegroundColor Red
    Write-Host "The original app.asar is not replaced unless all validation passes."
    if (Test-Path -LiteralPath $TempPath) { Remove-Item -LiteralPath $TempPath -Force -ErrorAction SilentlyContinue }
    throw
}
finally { if ($srcFs) { $srcFs.Dispose() } }
